import type { createAgent } from "@ui-sdk/react/agent"
import { createHistory, describeEntry, type HistoryEntry } from "@ui-sdk/react/history"
import { observe } from "@ui-sdk/react/observe"

// UI SDK marks its history helpers experimental, so nothing of theirs leaks into this module's types: an app depends
// on ActivityLog and ActivityEntry only, and a change upstream stays inside this file.

type Agent = ReturnType<typeof createAgent>

/** Who made a change: an agent, a person (keyboard, pointer, touch), or the app's own code. */
type ActivityActor = "agent" | "person" | "app"

type ActivityEntry = {
  id: string
  actor: ActivityActor
  /** UI SDK's source, like `"agent"`, `"keyboard"` or `"programmatic"`; `"record"` for one the app recorded. */
  source: string
  /** The control's accessible name, or the label the app recorded. */
  label: string
  /** A sentence for the list, like "Agent set Status to Done". */
  description: string
  /** When it was recorded, in ms since the epoch. */
  at: number
  /** Text on the control's row, like the title of the task whose status changed. */
  row?: string
  value?: unknown
  previous?: unknown
  /** Undone on its own by `undoActor`, and skipped when seeking. */
  reverted: boolean
  /** A password, card or one-time-code value: it reads `"[redacted]"` and is never put back. */
  redacted: boolean
}

/** A change the app records itself, like a task the agent moved, with how to take it back and do it again. */
type ActivityRecord = {
  label: string
  description: string
  actor?: ActivityActor
  value?: unknown
  previous?: unknown
  undo: () => unknown
  redo: () => unknown
}

/** A change a seek or an undo couldn't put back: refused, gone from the page, redacted, or a record that threw. */
type ActivityNotRestored = { id?: string; label: string; value?: unknown }

type ActivityLogSnapshot = { entries: readonly ActivityEntry[]; position: number; busy: boolean }

type ActivityLogOptions = {
  /** Records only controls inside this element, like one panel. Defaults to the whole page. */
  within?: Element | (() => Element | null | undefined)
  /** State keys worth an entry. @defaultValue ["value", "checked", "pressed"] */
  keys?: string[]
  /** Writes each control change's sentence, in the page's language; UI SDK's English one by default. */
  describe?: (change: { actor: ActivityActor; label: string; value: unknown; previous: unknown }) => string
  /** The clock, for tests. */
  now?: () => number
}

type ActivityLog = {
  /** The entries and the position, as one object that changes only when they do. */
  getSnapshot: () => ActivityLogSnapshot
  subscribe: (listener: () => void) => () => void
  /** Records a change of the app's own, after its controls' ones. */
  record: (change: ActivityRecord) => string
  canUndo: () => boolean
  canRedo: () => boolean
  undo: () => Promise<ActivityNotRestored[]>
  redo: () => Promise<ActivityNotRestored[]>
  /** Puts the page back to how it was after `position` entries, or forward again. */
  seek: (position: number) => Promise<ActivityNotRestored[]>
  /** Takes back every applied change one actor made, like the agent's, and keeps the rest. */
  undoActor: (actor: ActivityActor) => Promise<ActivityNotRestored[]>
  /** Forgets every entry and keeps the page as it is. */
  clear: () => void
  /** Stops recording. */
  destroy: () => void
}

type Item =
  | { kind: "control"; id: string; at: number }
  | { kind: "record"; id: string; at: number; change: ActivityRecord; reverted: boolean }

// Restoring runs one step at a time, in order: each step starts from the page the previous one left.
function inOrder<T>(list: readonly T[], run: (item: T) => Promise<ActivityNotRestored[]>) {
  return list.reduce<Promise<ActivityNotRestored[]>>(
    async (done, item) => [...(await done), ...(await run(item))],
    Promise.resolve([]),
  )
}

const personSources = ["keyboard", "mouse", "touch", "pen", "virtual"]

/** The actor behind a UI SDK source, like a change callback's `details.source`. */
function actorOf(source: string | undefined): ActivityActor {
  if (source === "agent") return "agent"
  if (source === "programmatic" || source === undefined) return "app"
  return "person"
}

function sourcesOf(actor: ActivityActor) {
  if (actor === "agent") return ["agent"]
  if (actor === "app") return ["programmatic"]
  return personSources
}

/**
 * Records changes to the page's UI SDK controls, from people and agents, and the app's own `record`s, and steps
 * back and forward through them. Create it once, in the browser, before the controls you want recorded render,
 * with the app's agent bridge: restoring goes through it, so its permissions and change callbacks still apply.
 */
function createActivityLog(agent: Agent, options: ActivityLogOptions = {}): ActivityLog {
  const now = options.now ?? Date.now
  const rows = new Map<string, string | undefined>()
  // Registered before the history, so a change's row is known when the history reports it.
  const stopObserving = observe(
    (change) => {
      rows.set(change.ref, change.row)
    },
    { within: options.within },
  )
  const history = createHistory(agent, { within: options.within, keys: options.keys })
  const listeners = new Set<() => void>()
  let items: Item[] = []
  let position = 0
  let busy = 0
  let snapshot: ActivityLogSnapshot = { entries: [], position: 0, busy: false }
  let counter = 0

  const describe = (entry: HistoryEntry) =>
    options.describe?.({
      actor: actorOf(entry.source),
      label: entry.label,
      value: entry.value,
      previous: entry.previous,
    }) ?? describeEntry(entry)

  const toEntry = (item: Item, byId: Map<string, HistoryEntry>): ActivityEntry | undefined => {
    if (item.kind === "record") {
      const { change } = item
      return {
        id: item.id,
        actor: change.actor ?? "person",
        source: "record",
        label: change.label,
        description: change.description,
        at: item.at,
        value: change.value,
        previous: change.previous,
        reverted: item.reverted,
        redacted: false,
      }
    }
    const entry = byId.get(item.id)
    if (!entry) return undefined
    return {
      id: entry.id,
      actor: actorOf(entry.source),
      source: entry.source,
      label: entry.label,
      description: describe(entry),
      at: item.at,
      row: rows.get(entry.ref),
      value: entry.value,
      previous: entry.previous,
      reverted: entry.reverted === true,
      redacted: entry.redacted === true,
    }
  }

  const emit = () => {
    const byId = new Map(history.entries().map((entry) => [entry.id, entry]))
    const entries = items.flatMap((item) => toEntry(item, byId) ?? [])
    snapshot = { entries, position, busy: busy > 0 }
    for (const listener of listeners) listener()
  }

  // A new change after stepping back drops the steps that were ahead, like undo in an editor.
  const append = (item: Item) => {
    items = [...items.slice(0, position), item]
    position = items.length
  }

  const stopHistory = history.subscribe(() => {
    const entries = history.entries()
    const ids = new Set(entries.map((entry) => entry.id))
    const known = new Set(items.map((item) => item.id))
    // The history forgets entries on clear() and drops the ones ahead of its position when a new change comes.
    const keep = (item: Item) => item.kind === "record" || ids.has(item.id)
    position = items.slice(0, position).filter(keep).length
    items = items.filter(keep)
    for (const entry of entries) if (!known.has(entry.id)) append({ kind: "control", id: entry.id, at: now() })
    emit()
  })

  const historyCount = (upTo: number) => items.slice(0, upTo).filter((item) => item.kind === "control").length

  const notRestored = (failed: { ref: string; key: string; value: unknown }[]) =>
    failed.map((step) => ({
      label: history.entries().find((entry) => entry.ref === step.ref && entry.key === step.key)?.label ?? step.ref,
      value: step.value,
    }))

  const runRecord = async (item: Extract<Item, { kind: "record" }>, direction: "undo" | "redo") => {
    try {
      await item.change[direction]()
      return []
    } catch {
      return [{ id: item.id, label: item.change.label, value: item.change.previous }]
    }
  }

  let turn: Promise<unknown> = Promise.resolve()
  const inTurn = <T>(run: () => Promise<T>) => {
    const next = turn.then(async () => {
      busy += 1
      emit()
      try {
        return await run()
      } finally {
        busy -= 1
        emit()
      }
    })
    turn = next.catch(() => {})
    return next
  }

  // Walks from the position to the target one item at a time. Control changes between records go back together in
  // one history seek; each record runs its own undo or redo, skipping those undoActor already took back.
  const seekTo = async (requested: number) => {
    const target = Math.max(0, Math.min(items.length, Math.round(requested)))
    const backward = target < position
    const order = backward
      ? items.slice(target, position).map((_, offset) => position - 1 - offset)
      : items.slice(position, target).map((_, offset) => position + offset)
    const failed = await inOrder(order, async (index) => {
      const item = items[index]
      if (item?.kind !== "record" || item.reverted) return []
      const controls = notRestored(await history.seek(historyCount(backward ? index + 1 : index)))
      return [...controls, ...(await runRecord(item, backward ? "undo" : "redo"))]
    })
    failed.push(...notRestored(await history.seek(historyCount(target))))
    position = target
    return failed
  }

  return {
    getSnapshot: () => snapshot,
    subscribe(listener) {
      listeners.add(listener)
      return () => {
        listeners.delete(listener)
      }
    },
    record(change) {
      counter += 1
      const id = `r${String(counter)}`
      append({ kind: "record", id, at: now(), change, reverted: false })
      emit()
      return id
    },
    canUndo: () => position > 0,
    canRedo: () => position < items.length,
    undo: () => inTurn(() => seekTo(position - 1)),
    redo: () => inTurn(() => seekTo(position + 1)),
    seek: (target) => inTurn(() => seekTo(target)),
    undoActor: (actor) =>
      inTurn(async () => {
        const controls = await inOrder(sourcesOf(actor), async (source) =>
          notRestored(await history.undoSource(source)),
        )
        const records = items
          .slice(0, position)
          .filter((item): item is Extract<Item, { kind: "record" }> => item.kind === "record")
          .filter((item) => !item.reverted && (item.change.actor ?? "person") === actor)
        const undone = await inOrder(records.toReversed(), async (item) => {
          const missed = await runRecord(item, "undo")
          if (missed.length === 0) item.reverted = true
          return missed
        })
        return [...controls, ...undone]
      }),
    clear() {
      history.clear()
      items = []
      position = 0
      emit()
    },
    destroy() {
      stopHistory()
      history.destroy()
      stopObserving()
      listeners.clear()
    },
  }
}

export { actorOf, createActivityLog }
export type {
  ActivityActor,
  ActivityEntry,
  ActivityLog,
  ActivityLogOptions,
  ActivityLogSnapshot,
  ActivityNotRestored,
  ActivityRecord,
}

import { definePrimitive } from "@ui-sdk/core"

import type { ActivityLog } from "@/components/ui/activity-log-store"

type ActivityLogOptions = {
  log?: Pick<ActivityLog, "getSnapshot" | "subscribe" | "undo" | "redo" | "seek">
}

function stateOf(log: ActivityLogOptions["log"]) {
  const snapshot = log?.getSnapshot()
  return {
    /** How many entries are applied: the position agents read. */
    value: snapshot?.position ?? 0,
    count: snapshot?.entries.length ?? 0,
    busy: snapshot?.busy ?? false,
  }
}

// The agent bridge passes arguments unchecked, and names an entry by its label or its position as a string.
function positionOf(target: unknown, count: number) {
  const position = typeof target === "string" && target.trim() !== "" ? Number(target) : target
  if (typeof position !== "number" || !Number.isInteger(position) || position < 0 || position > count) {
    throw new RangeError(`No position ${JSON.stringify(target)}: seek takes a whole number from 0 to ${String(count)}.`)
  }
  return position
}

const activityLog = definePrimitive({
  name: "activity-log",
  options: { log: "value" },
  state: (options: ActivityLogOptions) => stateOf(options.log),
  api: (context) => {
    const log = () => context.options().log
    let unsubscribe = log()?.subscribe(() => context.store.set(stateOf(log())))
    let current = log()
    context.onOptions((options) => {
      if (options.log === current) return
      unsubscribe?.()
      current = options.log
      unsubscribe = current?.subscribe(() => context.store.set(stateOf(current)))
      context.store.set(stateOf(current))
    })
    context.onDestroy(() => unsubscribe?.())
    return {
      /** Takes back the newest applied entry. Resolves with the changes it couldn't put back. */
      undo: async () => (await log()?.undo()) ?? [],
      /** Applies the next entry again. */
      redo: async () => (await log()?.redo()) ?? [],
      /** Puts the page back to how it was after `position` entries (0 is the start), or forward again. */
      seek: async (position: unknown) => {
        const target = positionOf(position, context.store.get().count)
        return (await log()?.seek(target)) ?? []
      },
      /** The entries as items, oldest first: their value is the position that seeking to them restores. */
      items: () =>
        (log()?.getSnapshot().entries ?? []).map((entry, index) => ({
          value: String(index + 1),
          label: entry.description,
        })),
    }
  },
  slots: (slot) => ({
    root: slot<{}, { position: number; count: number; canUndo: boolean; canRedo: boolean; busy: boolean }>({
      role: "group",
      state: (state) => ({
        position: state.value,
        count: state.count,
        canUndo: state.value > 0,
        canRedo: state.value < state.count,
        busy: state.busy,
      }),
      attrs: (state) => ({ "aria-busy": state.busy ? "true" : undefined, "data-busy": state.busy ? "" : undefined }),
    }),
    entry: slot<{ value: string }, { state: "applied" | "current" | "undone" }>({
      role: "button",
      focus: "native",
      props: { value: "string" },
      state: (state, part) => ({ state: entryState(Number(part.key), state.value) }),
      attrs: (state, part) => ({
        type: "button",
        "aria-current": Number(part.key) === state.value ? "step" : undefined,
        "data-state": entryState(Number(part.key), state.value),
      }),
      press: ({ api, key }) => void api.seek(key),
    }),
  }),
  agent: { actions: ["undo", "redo", "seek"], items: (api) => api.items() },
})

function entryState(position: number, current: number) {
  if (position === current) return "current"
  return position > current ? "undone" : "applied"
}

export { activityLog }
export type { ActivityLogOptions as ActivityLogPrimitiveOptions }

"use client"

import { createParts } from "@ui-sdk/react/primitive"
import { useSyncExternalStore, type ComponentProps, type ReactNode } from "react"
import { BotIcon, Redo2Icon, Undo2Icon, UserIcon, WorkflowIcon, type LucideIcon } from "lucide-react"

import { activityLog } from "@/components/ui/activity-log-primitive"
import type {
  ActivityActor,
  ActivityLog as ActivityLogStore,
  ActivityLogSnapshot,
} from "@/components/ui/activity-log-store"
import { Button } from "@/components/ui/button"
import { RelativeTime } from "@/components/ui/relative-time"
import { toast } from "@/components/ui/toast"
import type { Instant } from "@/lib/time"
import { cn, cnState } from "@/lib/utils"

const Parts = createParts(activityLog, { root: "div", entry: "button" })

const emptySnapshot: ActivityLogSnapshot = { entries: [], position: 0, busy: false }
const noop = () => () => {}

/** The log's entries, position and busy state, re-rendering when they change. */
function useActivityLog(log: ActivityLogStore | undefined): ActivityLogSnapshot {
  return useSyncExternalStore(
    log?.subscribe ?? noop,
    () => log?.getSnapshot() ?? emptySnapshot,
    () => log?.getSnapshot() ?? emptySnapshot,
  )
}

type ActivityLogLabels = {
  undo: string
  redo: string
  /** The entry that restores the page as it was before any change. */
  start: string
  empty: string
  /** Read after an entry that is undone, for screen readers. */
  undone: string
  /** Read after an entry `undoActor` took back. */
  reverted: string
  /** Read before each entry, for screen readers. */
  actors: Record<ActivityActor, string>
  /** What an agent asks a person before a seek that undoes more than `confirmAbove` entries. */
  confirmSeek: (count: number) => string
}

const activityLogLabels: ActivityLogLabels = {
  undo: "Undo",
  redo: "Redo",
  start: "Start",
  empty: "No changes yet",
  undone: "Undone",
  reverted: "Reverted",
  actors: { agent: "Agent", person: "Person", app: "App" },
  confirmSeek: (count) => `Undo the last ${String(count)} changes`,
}

const actorIcons = { agent: BotIcon, person: UserIcon, app: WorkflowIcon } satisfies Record<ActivityActor, LucideIcon>

// Cmd/Ctrl+Z in a text field undoes its typing, not the page.
function outsideTextField() {
  const active = typeof document === "undefined" ? null : document.activeElement
  if (!(active instanceof HTMLElement)) return true
  if (active.isContentEditable) return false
  if (active instanceof HTMLTextAreaElement) return false
  return (
    !(active instanceof HTMLInputElement) || ["checkbox", "radio", "button", "range", "color"].includes(active.type)
  )
}

type ActivityLogProps = Omit<ComponentProps<typeof Parts.Root>, "log" | "children"> & {
  log: ActivityLogStore
  /** Names the log, for screen readers and agents. */
  label: string
  labels?: Partial<Omit<ActivityLogLabels, "actors">> & { actors?: Partial<ActivityLogLabels["actors"]> }
  /** A heading beside Undo and Redo. */
  header?: ReactNode
  /** Seeks that undo more entries than this need a person's approval when an agent asks for them. */
  confirmAbove?: number
  /** Binds Cmd/Ctrl+Z and Shift+Cmd/Ctrl+Z, listed in `ShortcutsDialog`. Turn off for a second log on the page. */
  shortcuts?: boolean
  /** Pass one `useNow()` per screen. */
  now?: Instant
  locale?: string
}

/**
 * A list of the changes an `ActivityLog` recorded, newest first, with who made them and when. Pressing an entry puts
 * the page back to just after it; Undo and Redo step one entry.
 */
function ActivityLog({
  log,
  label,
  labels: labelsProp,
  header,
  confirmAbove = 3,
  shortcuts = true,
  now,
  locale,
  className,
  ...props
}: ActivityLogProps) {
  const labels = { ...activityLogLabels, ...labelsProp, actors: { ...activityLogLabels.actors, ...labelsProp?.actors } }
  const { entries, position } = useActivityLog(log)
  const confirm = (target: number) =>
    position - target > confirmAbove ? labels.confirmSeek(position - target) : undefined
  const entryClassName =
    "flex w-full items-start gap-items rounded-control px-inset-item py-inset-item text-start text-body-sm outline-none transition-colors duration-micro ease-standard hover:bg-accent hover:text-accent-foreground focus-visible:ring-2 focus-visible:ring-ring aria-[current=step]:bg-accent aria-[current=step]:text-accent-foreground data-[state=undone]:text-muted-foreground disabled:cursor-not-allowed"

  return (
    <Parts.Root
      log={log}
      aria-label={label}
      className={cnState("flex min-h-0 flex-col gap-items", className)}
      {...props}
    >
      {({ canUndo, canRedo }) => (
        <>
          <div data-slot="activity-log-header" className="flex items-center gap-inline">
            <div className="min-w-0 flex-1">{header}</div>
            <Button
              variant="ghost"
              size="icon"
              aria-label={labels.undo}
              shortcut={shortcuts ? "mod+z" : undefined}
              shortcutWhen={outsideTextField}
              disabled={!canUndo}
              onClick={() => log.undo()}
            >
              <Undo2Icon className="rtl:-scale-x-100" />
            </Button>
            <Button
              variant="ghost"
              size="icon"
              aria-label={labels.redo}
              shortcut={shortcuts ? "mod+shift+z" : undefined}
              shortcutWhen={outsideTextField}
              disabled={!canRedo}
              onClick={() => log.redo()}
            >
              <Redo2Icon className="rtl:-scale-x-100" />
            </Button>
          </div>
          {entries.length === 0 ? (
            <p data-slot="activity-log-empty" className="px-inset-item text-body-sm text-muted-foreground">
              {labels.empty}
            </p>
          ) : (
            <ol data-slot="activity-log-list" className="flex min-h-0 flex-col overflow-y-auto">
              {entries.toReversed().map((entry, reversedIndex) => {
                const target = entries.length - reversedIndex
                const Icon = actorIcons[entry.actor]
                return (
                  <li key={entry.id} data-actor={entry.actor} className="flex">
                    <Parts.Entry value={String(target)} data-agent-confirm={confirm(target)} className={entryClassName}>
                      <Icon aria-hidden className="mt-px size-3.5 shrink-0 text-muted-foreground" />
                      <span className="flex min-w-0 flex-col">
                        <span className={cn(entry.reverted && "line-through")}>
                          <span className="sr-only">{labels.actors[entry.actor]}: </span>
                          {entry.description}
                        </span>
                        <span className="flex flex-wrap items-baseline gap-x-inline text-caption text-muted-foreground">
                          {entry.row !== undefined && <span className="truncate">{entry.row}</span>}
                          <RelativeTime value={entry.at} now={now} locale={locale} formatStyle="short" />
                          {target > position && <span className="sr-only">{labels.undone}</span>}
                          {entry.reverted && <span>{labels.reverted}</span>}
                        </span>
                      </span>
                    </Parts.Entry>
                  </li>
                )
              })}
              <li className="flex">
                <Parts.Entry value="0" data-agent-confirm={confirm(0)} className={entryClassName}>
                  {labels.start}
                </Parts.Entry>
              </li>
            </ol>
          )}
        </>
      )}
    </Parts.Root>
  )
}

type UndoToastOptions = {
  /** Takes the change back. Without it, `log` steps back to just before the newest entry. */
  onUndo?: () => unknown
  log?: Pick<ActivityLogStore, "getSnapshot" | "seek">
  description?: string
  labels?: { undo?: string }
  /** A queue from `createToaster()`; the shared one by default. */
  toaster?: typeof toast
}

/** A toast with an Undo action, for a change that just happened: `undoToast("Task archived", { log })`. */
function undoToast(title: string, { onUndo, log, description, labels, toaster }: UndoToastOptions = {}) {
  let before = log ? log.getSnapshot().position - 1 : undefined
  // Called from a change callback, the change is recorded once the callback returns.
  queueMicrotask(() => {
    if (log) before = log.getSnapshot().position - 1
  })
  const show = toaster ?? toast
  return show(title, {
    description,
    action: {
      label: labels?.undo ?? activityLogLabels.undo,
      onAction: () => (onUndo ? onUndo() : before !== undefined && before >= 0 ? log?.seek(before) : undefined),
    },
  })
}

export { ActivityLog, activityLogLabels, undoToast, useActivityLog }
export type { ActivityLogLabels, ActivityLogProps, UndoToastOptions }
